namespace sv_e44d286cfc7d48c08e9caa6de19a5c16.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse and notifies
/// all subscribed components when the selection changes.
/// Scoped lifetime = one instance per circuit = per-user isolation.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "WH-001", Name = "Warehouse A — North" },
        new() { Id = "WH-002", Name = "Warehouse B — South" },
        new() { Id = "WH-003", Name = "Warehouse C — East" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo Current { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.Find(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != Current.Id)
        {
            Current = warehouse;
            OnChange?.Invoke();
        }
    }
}

namespace sv_e44d286cfc7d48c08e9caa6de19a5c16.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribers when new data arrives. The polling loop lives in the
/// dashboard component; this service owns the data and the notification event.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LowStockCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query — returns a random count 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by the polling component after fetching fresh data.
    /// Updates the cached count and notifies ALL subscribers.
    /// </summary>
    public void UpdateCount(int count)
    {
        LowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }
}

