    {
        // Subscribe to warehouse changes so the dashboard re-renders
        // when the selector (in the layout) picks a different warehouse.
        _warehouseHandler = () => InvokeAsync(async () =>
        {
            // Warehouse changed — poll immediately for the new warehouse.
            await PollAsync();
            StateHasChanged();
        });
        WarehouseState.OnChange += _warehouseHandler;

        // Subscribe to alert count changes (this fires from our own poll,
        // but also if any other component updates the count).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Initial fetch + start the polling loop.
        await PollAsync();
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.Current.Id);
        _lastCheck = DateTime.Now;
        AlertService.UpdateCount(count);
    }

    private async Task PollLoopAsync(CancellationToken token)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(token))
            {
                await InvokeAsync(async () =>
                {
                    await PollAsync();
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

